-- Daily challenges for 2026-11-20: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-20. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('enjoying-the-night-sky', 'Enjoying the Night Sky', 'For anyone who rarely looks up after dark. Each day is one small way to notice the moon, the stars and the changing evening sky, from a doorway, a balcony or a quiet walk, and let it bring a little wonder.', 'Mindfulness', 365, array['Mindfulness', 'Self-Care']::text[], 1, '2026-11-20T17:00:00+00:00'::timestamptz),
  ('speaking-kindly-about-others', 'Speaking Kindly About Others', 'For anyone who wants their words about people to match how they would want to be spoken of. Each day is one small way to skip gossip, give credit and say something good about someone who is not in the room.', 'Kindness', 365, array['Relationships', 'Values', 'Communication']::text[], 1, '2026-11-20T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('enjoying-the-night-sky', 'speaking-kindly-about-others');

